FIELD_DEFS = 'interface figure\n  function name(self) -> string\n  function area(self) -> real\n  subroutine grow(inout self, real :: k)\nend interface\n\nrecord circle is figure\n  string :: label = "circle"\n  real :: r = 1.0\n  function name(self) -> string\n    return self.label\n  end function\n  function area(self) -> real\n    return 3.0 * self.r ** 2\n  end function\n  subroutine grow(inout self, real :: k)\n    @self.r = self.r * k\n  end subroutine\nend record\n\nrecord rect is figure\n  real :: w = 2.0\n  function name(self) -> string\n    return "rect"\n  end function\n  function area(self) -> real\n    return self.w\n  end function\n  subroutine grow(inout self, real :: k)\n    @self.w = self.w * k\n  end subroutine\nend record\n\nrecord scene\n  figure[3] :: items\n  figure :: top\n  real[3] :: v = 1.5\n  int32[2] :: n\n  logical[2] :: flags\n  rect[2] :: rs\n  int :: count = 0\nend record\n\nrecord holder\n  scene :: inner\n  string :: tag = "h"\nend record\n\nrecord plain\n  real[2] :: v = 2.0\n  int :: k = 1\nend record\n\nsubroutine add(inout scene :: s, figure :: f)\n  @s.count = s.count + 1\n  @s.items[s.count] = f\nend subroutine\n\nfunction total(scene :: s) -> real\n  real :: t = 0.0\n  int :: i\n  do i = 1, s.count\n    t = t + s.items[i].area()\n  end do\n  return t\nend function\n\nfunction topname(scene :: s) -> string\n  return s.top.name()\nend function\n\nfunction full() -> scene\n  scene :: s\n  call add(@s, circle("a", 2.0))\n  call add(@s, rect(3.0))\n  call add(@s, circle("b", 1.0))\n  s.top = rect(7.0)\n  return s\nend function\n\nfunction unfull() -> scene\n  scene :: s\n  return s\nend function\nsubroutine show_f(figure :: f)\n  println(f.name(), f.area())\nend subroutine\n'
