MODULE_DEFS = 'module consts\n  public const int :: n = 7\n  public const int32 :: small = 12\n  public const real :: pi2 = 6.28\n  public const real32 :: half = 0.5\n  public const string :: greeting = "hello"\n  public const logical :: yes = true\n  public const real :: tau = 2.0 * pi2\n  public const int :: sq3 = 9\n  const int :: hidden = 99\n\n  public function use_hidden() -> int\n    return hidden + n\n  end function\n\n  function helper(int :: x) -> int\n    return x + 1\n  end function\n\n  public function twice(int :: x) -> int\n    return helper(helper(x))\n  end function\nend module\n\nmodule other\n  use consts: n, twice\n\n  public int :: counter = 0\n  public real :: acc = 1.5\n  public string :: name = "base"\n  public int32 :: small_count = 5\n\n  function helper(int :: x) -> int\n    return x * 10\n  end function\n\n  public function scaled(int :: x) -> int\n    return helper(x) + twice(x) + n\n  end function\n\n  public subroutine bump(int :: by)\n    @counter = counter + by\n    @acc = acc * 2.0\n    @name = name + "!"\n    @small_count = small_count + 1\n  end subroutine\n\n  public subroutine reset()\n    @counter = 0\n  end subroutine\n\n  public subroutine into(inout int :: v)\n    @v = v + counter\n  end subroutine\n\n  public subroutine setit(out int :: v)\n    @v = counter * 2\n  end subroutine\nend module\n\nmodule shapes\n  public record pt\n    real :: x = 0.0\n    real :: y = 0.0\n\n    function norm2(self) -> real\n      return self.x ** 2 + self.y ** 2\n    end function\n  end record\n\n  public interface figure\n    function area(self) -> real\n  end interface\n\n  public record sq is figure\n    real :: s = 2.0\n    function area(self) -> real\n      return self.s ** 2\n    end function\n  end record\n\n  public function origin() -> pt\n    return pt(0.0, 0.0)\n  end function\n\n  public function mid(pt :: a, pt :: b) -> pt\n    return pt((a.x + b.x) / 2.0, (a.y + b.y) / 2.0)\n  end function\nend module\n\nmodule uses_shapes\n  use shapes: pt, mid, figure, sq\n\n  public function centroid(pt :: a, pt :: b, pt :: c) -> pt\n    return mid(mid(a, b), c)\n  end function\n\n  public function total(figure :: f) -> real\n    return f.area() * 2.0\n  end function\nend module\n\nfunction inner(int :: k) -> int\n  use consts: n, twice\n  return twice(k) + n\nend function\n'
